// ponytail: minimal static geometry for 18 Iraqi governorates and community places
export interface Governorate {
  id: string;
  nameEn: string;
  nameAr: string;
  capital: string;
  region: string;
  population: string;
  lat: number;
  lng: number;
  center: [number, number];
  path: string;
}

export interface CommunityReview {
  id: string;
  author: string;
  rating: number;
  comment: string;
  date: string;
}

export interface LocalSpot {
  id: string;
  name: string;
  category: string;
  governorate: string;
  governorateId: string;
  district: string;
  lat: number;
  lng: number;
  phone: string;
  whatsapp: string;
  rating: number;
  reviewsCount: number;
  status: "مفتوح الآن" | "يغلق قريباً" | "مغلق";
  notes: string;
  isVerified: boolean;
  reviews: CommunityReview[];
}

