export function projectToSvg(lng: number, lat: number): [number, number] {
  const minLon = 38.794905311000036;
  const minLat = 28.99912994400006;
  const cosLat = 0.8370858162761645;
  const scale = 85.18881738661366;
  const padX = 35;
  const padY = 35;
  const height = 780;

  const x = padX + (lng - minLon) * cosLat * scale;
  const y = height - padY - (lat - minLat) * scale;
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
}

export function calculateDistanceKm(
  lat1: number,
  lon1: number,
  lat2: number,
  lon2: number
): number {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return Math.round(R * c * 10) / 10;
}

